// Writes freeze-manifest.json: every file needed for offline review with
// SHA-256, bytes and symlink targets, plus the materialized tool closure keyed
// to package-lock integrity. Scratch (trial/work) and launcher files are listed
// as excluded, not hashed.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..', '..');
const OUTPUT = 'freeze-manifest.json';
const LAUNCHER = new Set(['launch-public.py', 'process.json', 'prompt.md', 'public-events.jsonl', 'result.json', 'response.json', 'final-response.md', 'process-completion.json']);
const EXCLUDED_PREFIXES = ['trial/work/'];

const sha256 = data => crypto.createHash('sha256').update(data).digest('hex');
const entries = [];
function walk(relative) {
  for (const name of fs.readdirSync(path.join(root, relative)).sort()) {
    const rel = relative ? `${relative}/${name}` : name;
    const abs = path.join(root, rel);
    const stat = fs.lstatSync(abs);
    if (stat.isSymbolicLink()) entries.push({ path: rel, type: 'symlink', target: fs.readlinkSync(abs) });
    else if (stat.isDirectory()) { if (!EXCLUDED_PREFIXES.some(p => (rel + '/').startsWith(p))) walk(rel); }
    else entries.push({ path: rel, type: 'file', bytes: stat.size, mode: (stat.mode & 0o777).toString(8), sha256: sha256(fs.readFileSync(abs)) });
  }
}
walk('');

const groupOf = rel => LAUNCHER.has(rel) ? 'launcher-excluded'
  : rel.startsWith('trial/node_modules/') ? 'tool-closure'
  : rel.startsWith('results/') || rel.startsWith('prior/') || rel.startsWith('provenance/') ? 'evidence'
  : 'subject';
const files = entries.filter(e => e.path !== OUTPUT && !LAUNCHER.has(e.path)).map(e => ({ group: groupOf(e.path), ...e }));

const lock = JSON.parse(fs.readFileSync(path.join(root, 'trial/package-lock.json'), 'utf8'));
const packages = Object.entries(lock.packages).filter(([key]) => key).map(([key, meta]) => {
  const prefix = `trial/${key}/`;
  const tree = files.filter(f => f.path.startsWith(prefix) && !f.path.slice(prefix.length).includes('node_modules/'));
  const manifest = JSON.parse(fs.readFileSync(path.join(root, 'trial', key, 'package.json'), 'utf8'));
  return {
    path: key, name: manifest.name, version: manifest.version, lockVersion: meta.version, lockIntegrity: meta.integrity, license: meta.license,
    hasInstallScript: !!meta.hasInstallScript, versionMatchesLock: manifest.version === meta.version,
    files: tree.length, treeSha256: sha256(tree.map(f => `${f.type}\0${f.path.slice(prefix.length)}\0${f.sha256 ?? f.target}`).join('\n')),
  };
});

const aggregate = sha256(files.map(f => `${f.type}\0${f.path}\0${f.sha256 ?? f.target}`).join('\n'));
const counts = {};
for (const f of files) counts[f.group] = (counts[f.group] ?? 0) + 1;
fs.writeFileSync(path.join(root, OUTPUT), JSON.stringify({
  schemaVersion: 1,
  standing: 'author freeze candidate for root freezing and independent review; not an acceptance record',
  root,
  generatedWith: { node: process.version },
  excluded: { scratch: EXCLUDED_PREFIXES, launcher: [...LAUNCHER].filter(name => fs.existsSync(path.join(root, name))).sort() },
  aggregateSha256: aggregate, counts,
  toolClosure: {
    packages: packages.length, allVersionsMatchLock: packages.every(p => p.versionMatchesLock), installScripts: packages.filter(p => p.hasInstallScript).map(p => p.path),
    note: 'Materialized with npm install --ignore-scripts from the registry in comparison-01 and byte-copied here (cp -Rp); tarball integrity is attested by the lockfile, not recomputed per package. dependency-cruiser and typescript tarballs are archived in provenance/.',
    packageList: packages,
  },
  files,
}, null, 2) + '\n');
process.stdout.write(`${files.length} entries ${JSON.stringify(counts)} packages ${packages.length} aggregate ${aggregate}\n`);
