146	  if (format === 'invalid') return { unsupported: 'nearest package.json is not valid JSON' };
147	  if (dep.moduleSystem === 'cjs') return { mode: 'require' };
148	  if (dep.dynamic === true) return { mode: 'import' };
149	  if (platform === 'browser') return { mode: 'import' };
150	  return { mode: format === 'commonjs' ? 'require' : 'import' };
